// ─────────────────────────────────────────────────────────────────
// Session schedule — Layman-friendly Monday teasers & Wednesday reminders
// ─────────────────────────────────────────────────────────────────
const sessions = [
  {
    week: 1,
    sendOnMonday: '2026-10-05',
    sessionDate:  'Wednesday 7th October',
    wednesday:    '2026-10-07',
    topic:        'Optimize Your Campaigns with Meta Advantage+',
    mondayMessage: (name) => "Hi " + name + "! This Wednesday at 11 AM EAT: Learn how Meta's AI can automatically find your best paying customers without wasting your budget. Check your email for the Zoom link! - WYLDE",
    wednesdayMessage: (name) => "Good morning " + name + "! Today's Meta Transform with AI session starts at 11:00 AM EAT (in 2 hours). Check your email for your personal Zoom join link and get ready. See you soon! - WYLDE"
  },
  {
    week: 2,
    sendOnMonday: '2026-10-12',
    sessionDate:  'Wednesday 14th October',
    wednesday:    '2026-10-14',
    topic:        'Optimize Your Ad Creatives with Advantage+',
    mondayMessage: (name) => "Hi " + name + "! This Wednesday at 11 AM EAT: Discover how to use AI to create eye-catching photos and videos that make customers stop scrolling and buy. Zoom link is in your email! - WYLDE",
    wednesdayMessage: (name) => "Good morning " + name + "! Today's Meta Transform with AI session starts at 11:00 AM EAT (in 2 hours). Check your email for your personal Zoom join link and get ready. See you soon! - WYLDE"
  },
  {
    week: 3,
    sendOnMonday: '2026-10-19',
    sessionDate:  'Wednesday 21st October',
    wednesday:    '2026-10-21',
    topic:        'Opportunity Score',
    mondayMessage: (name) => "Hi " + name + "! This Wednesday at 11 AM EAT: Discover Meta's health score tool that shows exactly where your ads are losing money and how to fix them instantly. See you on Zoom! - WYLDE",
    wednesdayMessage: (name) => "Good morning " + name + "! Today's Meta Transform with AI session starts at 11:00 AM EAT (in 2 hours). Check your email for your personal Zoom join link and get ready. See you soon! - WYLDE"
  },
  {
    week: 4,
    sendOnMonday: '2026-10-26',
    sessionDate:  'Wednesday 28th October',
    wednesday:    '2026-10-28',
    topic:        'WhatsApp Business Platform for Effective Business Messaging',
    mondayMessage: (name) => "Hi " + name + "! This Wednesday at 11 AM EAT: Learn how to turn customer WhatsApp chats into instant paying orders using automated messaging tools. Check your email for the link! - WYLDE",
    wednesdayMessage: (name) => "Good morning " + name + "! Today's Meta Transform with AI session starts at 11:00 AM EAT (in 2 hours). Check your email for your personal Zoom join link and get ready. See you soon! - WYLDE"
  },
  {
    week: 5,
    sendOnMonday: '2026-11-02',
    sessionDate:  'Wednesday 4th November',
    wednesday:    '2026-11-04',
    topic:        'Increase Campaign Performance with Partnership Ads',
    mondayMessage: (name) => "Hi " + name + "! Final session this Wednesday at 11 AM EAT: Learn how teaming up with creators and other businesses on Meta can double your reach and sales. Don't miss out! - WYLDE",
    wednesdayMessage: (name) => "Good morning " + name + "! The final Meta Transform with AI session starts at 11:00 AM EAT (in 2 hours). Check your email for your personal Zoom join link. Let's finish strong! - WYLDE"
  }
];

const today = new Date().toISOString().split('T')[0];

let activeSession = null;
let msgType = null;

for (const s of sessions) {
  if (s.sendOnMonday === today) {
    activeSession = s;
    msgType = 'monday';
    break;
  }
  if (s.wednesday === today) {
    activeSession = s;
    msgType = 'wednesday';
    break;
  }
}

// Fallback for manual testing inside n8n:
if (!activeSession) {
  const isScheduled = typeof $execution !== 'undefined' && $execution && $execution.mode === 'trigger';
  if (isScheduled) {
    return [];
  }
  activeSession = sessions[0];
  msgType = 'monday';
}

const items = $input.all();
return items.map(item => {
  const firstName = (item.json['First Name'] || 'Participant').trim();
  const text = msgType === 'wednesday' 
    ? activeSession.wednesdayMessage(firstName)
    : activeSession.mondayMessage(firstName);

  return {
    json: {
      ...item.json,
      sessionWeek:  activeSession.week,
      sessionDate:  activeSession.sessionDate,
      topic:        activeSession.topic,
      smsType:      msgType,
      smsMessage:   text
    }
  };
});

// Build the smslist array for Advanta bulk endpoint
// Phone numbers must be in international format without +: 2547XXXXXXXX

const ADVANTA_API_KEY   = 'YOUR_ADVANTA_API_KEY';
const ADVANTA_PARTNER_ID = 'YOUR_ADVANTA_PARTNER_ID';
const ADVANTA_SENDER_ID  = 'YOUR_ADVANTA_SENDER_ID';

const smslist = $input.all().map((item, index) => {
  // Normalise phone: remove spaces, dashes, leading +
  let phone = (item.json['Phone'] || '').replace(/[^0-9]/g, '');
  // Convert 07XXXXXXXX -> 2547XXXXXXXX
  if (phone.startsWith('0')) phone = '254' + phone.slice(1);
  // Convert +254... -> 254...
  if (phone.startsWith('254') === false) phone = '254' + phone;

  return {
    partnerID:    ADVANTA_PARTNER_ID,
    apikey:       ADVANTA_API_KEY,
    pass_type:    'plain',
    clientsmsid:  index + 1,
    mobile:       phone,
    message:      item.json.smsMessage,
    shortcode:    ADVANTA_SENDER_ID
  };
});

return [{
  json: {
    apikey:    ADVANTA_API_KEY,
    partnerID: ADVANTA_PARTNER_ID,
    smslist:   smslist
  }
}];
